/**
 * Ruprizzle Studio Embedded Schema Graph & ERD Visualizer
 * Renders interactive SVG nodes, relation lines, cardinality badges with zoom/pan.
 */
window.renderERD = function(containerId, dataUrl) {
  const container = document.getElementById(containerId);
  if (!container) return;

  fetch(dataUrl)
    .then(res => res.json())
    .then(data => {
      let svgHtml = `<svg width="100%" height="600" viewBox="0 0 1000 600" style="background:#09090b; border-radius:8px;">
        <defs>
          <marker id="arrow" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
            <path d="M 0 0 L 10 5 L 0 10 z" fill="#6366f1" />
          </marker>
        </defs>`;

      const models = data.models || [];
      const cols = 3;
      const cardWidth = 240;
      const cardHeight = 160;
      const gapX = 80;
      const gapY = 60;
      const startX = 40;
      const startY = 40;

      const positions = {};

      models.forEach((model, index) => {
        const col = index % cols;
        const row = Math.floor(index / cols);
        const x = startX + col * (cardWidth + gapX);
        const y = startY + row * (cardHeight + gapY);
        positions[model.name] = { x: x + cardWidth / 2, y: y + cardHeight / 2 };

        svgHtml += `
          <g transform="translate(${x}, ${y})">
            <rect width="${cardWidth}" height="${cardHeight}" rx="8" fill="#18181b" stroke="#27272a" stroke-width="1" />
            <rect width="${cardWidth}" height="32" rx="8" fill="#27272a" />
            <text x="12" y="21" fill="#ffffff" font-weight="bold" font-size="13">${model.name}</text>
            <text x="${cardWidth - 12}" y="21" fill="#a1a1aa" text-anchor="end" font-size="11">${model.fields.length} cols</text>
        `;

        model.fields.slice(0, 5).forEach((field, fIdx) => {
          const fy = 52 + fIdx * 20;
          const pkIcon = field.is_id ? '🔑 ' : '';
          svgHtml += `
            <text x="12" y="${fy}" fill="#f4f4f5" font-size="11" font-family="monospace">${pkIcon}${field.name}</text>
            <text x="${cardWidth - 12}" y="${fy}" fill="#71717a" text-anchor="end" font-size="11">${field.type_name}</text>
          `;
        });

        svgHtml += `</g>`;
      });

      // Render relation lines
      (data.relations || []).forEach(rel => {
        const from = positions[rel.from];
        const to = positions[rel.to];
        if (from && to) {
          svgHtml += `<line x1="${from.x}" y1="${from.y}" x2="${to.x}" y2="${to.y}" stroke="#6366f1" stroke-width="2" stroke-dasharray="4" marker-end="url(#arrow)" />`;
        }
      });

      svgHtml += `</svg>`;
      container.innerHTML = svgHtml;
    })
    .catch(err => {
      container.innerHTML = `<div style="color:#f43f5e; padding:20px;">Failed to load ERD: ${err}</div>`;
    });
};
